B64
tar xzf /tmp/gt.tgz -C /tmp/garita && find /tmp/garita -type f | wc -l
git clone -q --depth 1 --branch twin-ids https://github.com/webgpu-demos/procedural-sanjuan psj && cd psj
npm ci --no-audit --no-fund > /dev/null 2>&1; echo "npm ci done $(date -u +%T)"
npm test 2>&1 | tail -3
node --max-old-space-size=4096 tools/pipeline/fetch.mjs --area=condado --garita=/tmp/garita > "$OUT/fetch.txt" 2>&1; echo "fetch exit $? $(date -u +%T)"; grep -i garita "$OUT/fetch.txt"
node --max-old-space-size=6144 tools/pipeline/compile.mjs --area=condado > "$OUT/compile.txt" 2>&1; echo "compile exit $? $(date -u +%T)"
grep -iE "garita|gers|heights from|buildings:" "$OUT/compile.txt"
cd public/tiles/condado && ls *.ids | wc -l && cat *.ids | awk -F, '{n++; if($1!="")g++; if($2!="")o++} END {print n" lines, "g" with gers, "o" with osm"}'
python3 - <<'PY'
import json; m=json.load(open('manifest.json')); print(sum(1 for t in m['tiles'] if t.get('ids')), 'tiles with ids of', len(m['tiles'])); print(m['attribution'])
PY
cd .. && tar czf "$OUT/condado_tiles.tgz" condado && ls -l "$OUT/condado_tiles.tgz"
date -u
